N = int(input())
material = list(map(int, input().split()))
A = list(map(int, input().split()))
B = list(map(int, input().split()))

def canmake(K): # K servings of dishes A and B
    for i in range(K + 1):
        local_judge = True
        for j in range(N):
            if A[j] * i + B[j] * (K - i) > material[j]:
                local_judge = False
                break
        if local_judge:
            return True
    return False

L, R = 0, sum(material) // min(min(A), min(B)) + 1
while R - L > 1:
    C = (R + L) // 2
    if canmake(C):
        L = C
    else:
        R = C

print(L)
